const game=new GF.Game({id:'harbor-courier',title:'Harbor Courier',width:960,height:540,palette:['#1679A8','#F8D66D','#F47B62','#F5F1DF','#247B5A'],background:'#1679A8',seed:314159});
const C={water:'#1679A8',foam:'#bcece3',sand:'#F8D66D',road:'#F5F1DF',ink:'#17445a',coral:'#F47B62',leaf:'#247B5A',cream:'#fff9e8',curb:'#d8c9a9'};
const emit=(type,data)=>game.event(type,data);
const play={
 init(){
  this.orders=[
   {depot:[118,270],home:[218,270],name:'Lighthouse Café',color:'#F8D66D'},
   {depot:[382,270],home:[520,370],name:'Coral House',color:'#F47B62'},
   {depot:[650,270],home:[810,270],name:'Marina Market',color:'#247B5A'}
  ];
  this.blocks=[
   {x:282,y:232,w:42,h:74,type:'planter'},
   {x:418,y:92,w:150,h:108,type:'building'},
   {x:670,y:342,w:142,h:78,type:'building'},
   {x:95,y:372,w:154,h:58,type:'hedge'},
   {x:840,y:92,w:30,h:128,type:'dock fence'}
  ];
  this.rings=[];
 },
 reset(){
  this.run=(this.run||0)+1;
  this.x=118;this.y=270;this.vx=0;this.vy=0;this.order=0;this.carry=false;
  this.travel=0;this.bump=0;this.dust=0;this.detour=false;this.waitForLane=false;
  this.driveSent=false;this.collisionSent=false;this.freshPending=this.run>1;
  this.timer=this.run===1?90:5;this.warning=false;this.terminalQueued=false;
  this.rings.length=0;
 },
 solid(x,y){
  if(x<38||x>922||y<82||y>494)return 'water edge';
  for(const b of this.blocks){
   if(x>b.x-13&&x<b.x+b.w+13&&y>b.y-13&&y<b.y+b.h+13)return b.type;
  }
  return '';
 },
 collide(kind){
  if(this.bump>0)return;
  this.bump=.2;game.shake(3,.18);game.flash(C.coral,.1);GF.Sfx.noise({dur:.045,vol:.1,freq:600});
  if(game.time>1.25&&game.score>0&&!this.collisionSent){
   this.collisionSent=true;
   emit('obstacle_collision_blocked',{kind:kind,score:game.score,blocked:true});
  }
 },
 objective(){
  if(this.waitForLane)return [this.x,this.y];
  if(this.detour)return [300,342];
  const o=this.orders[Math.min(this.order,2)];
  return this.carry?o.home:o.depot;
 },
 pickup(){
  this.carry=true;
  const o=this.orders[this.order];
  game.burst(this.x,this.y,{count:12,speed:82,size:3,life:.42,colors:[C.cream,C.sand,o.color],gravity:85});
  GF.Sfx.beep({freq:510,to:740,dur:.11,type:'triangle',vol:.22});
 },
 deliver(){
  const o=this.orders[this.order];
  const before=game.score;
  const bonus=Math.max(0,Math.floor(this.timer));
  const points=100+bonus;
  game.addScore(points);
  emit('score_change',{before:before,after:game.score,delivery:o.name});
  this.carry=false;this.order++;this.timer=Math.min(99,this.timer+3);
  game.hitStop(.08);game.shake(4,.18);game.flash('#fff2c4',.35);
  game.burst(this.x,this.y,{count:30,speed:165,size:4,life:.8,colors:[o.color,C.sand,C.cream,C.coral],gravity:165});
  this.rings.push({x:this.x,y:this.y,r:15,life:.76,color:o.color});
  GF.Sfx.melody([[784,.07],[988,.08],[1175,.14]],{type:'triangle',vol:.22});
  if(this.order===1){this.waitForLane=true;}
  if(this.order>=3){
   emit('delivery_sequence_completed',{delivered:3,destinations:['Lighthouse Café','Coral House','Marina Market'],score:game.score});
   game.win({message:'HARBOR ROUTE COMPLETE!'});
   if(!this.terminalQueued){
    this.terminalQueued=true;
    setTimeout(()=>{if(game.state==='won')game.restart();},1500);
   }
  }
 },
 update(dt){
  dt=Math.min(dt,.05);
  this.bump=Math.max(0,this.bump-dt);
  this.timer=Math.max(0,this.timer-dt);
  if(this.freshPending&&game.time>1.3){
   this.freshPending=false;
   emit('fresh_run_started',{run:this.run,timer:Math.ceil(this.timer),fresh:true});
  }
  if(this.timer<=10&&!this.warning){this.warning=true;game.flash(C.coral,.2);GF.Sfx.beep({freq:660,dur:.07,type:'square',vol:.14});}
  if(this.timer<=0){game.gameOver({message:'SHIFT TIME RAN OUT — '+this.order+' / 3 DELIVERED'});return;}
  if(this.waitForLane&&game.time>1.3)this.waitForLane=false;
  const goal=this.objective();
  let dx=goal[0]-this.x,dy=goal[1]-this.y,dl=Math.hypot(dx,dy)||1;
  let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
  let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
  const il=Math.hypot(ix,iy);if(il){ix/=il;iy/=il;}
  let ax=dx/dl*.92+ix*.28,ay=dy/dl*.92+iy*.28;
  const al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;
  const speed=this.run===1?265:145;
  this.vx=ax*speed;this.vy=ay*speed;
  const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;
  let hit=this.solid(nx,this.y);
  if(hit){this.vx=0;this.collide(hit);if(this.order===1&&!this.carry)this.detour=true;}else this.x=nx;
  hit=this.solid(this.x,ny);
  if(hit){this.vy=0;this.collide(hit);if(this.order===1&&!this.carry)this.detour=true;}else this.y=ny;
  this.travel+=Math.hypot(this.vx,this.vy)*dt;
  if(game.time>1.25&&game.score>0&&this.travel>20&&!this.driveSent){
   this.driveSent=true;
   emit('courier_drive_confirmed',{distance:Math.round(this.travel),score:game.score,moving:true});
  }
  if(this.detour&&Math.hypot(this.x-300,this.y-342)<23)this.detour=false;
  const o=this.orders[Math.min(this.order,2)];
  const active=this.carry?o.home:o.depot;
  if(!this.waitForLane&&!this.detour&&Math.hypot(this.x-active[0],this.y-active[1])<28){if(this.carry)this.deliver();else this.pickup();}
  if(this.dust<=0&&Math.hypot(this.vx,this.vy)>30){this.dust=.16;game.burst(this.x-8,this.y+8,{count:1,speed:14,size:2,life:.28,colors:['#d7c7a3'],gravity:0});}
  this.dust-=dt;
  for(let i=this.rings.length-1;i>=0;i--){const r=this.rings[i];r.life-=dt;r.r+=86*dt;if(r.life<=0)this.rings.splice(i,1);}
 },
 marker(ctx,pt,o,parcel,dim){
  const pulse=1+Math.sin(game.time*5)*.08;
  ctx.save();ctx.globalAlpha=dim?.22:1;ctx.fillStyle=o.color;ctx.globalAlpha*=.18;ctx.beginPath();ctx.arc(pt[0],pt[1],38*pulse,0,Math.PI*2);ctx.fill();
  ctx.globalAlpha=dim?.42:1;ctx.strokeStyle=o.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(pt[0],pt[1],25,0,Math.PI*2);ctx.stroke();ctx.fillStyle=C.cream;ctx.beginPath();ctx.arc(pt[0],pt[1],16,0,Math.PI*2);ctx.fill();
  ctx.fillStyle=o.color;if(parcel){ctx.fillRect(pt[0]-8,pt[1]-6,16,12);ctx.strokeStyle=C.ink;ctx.lineWidth=1;ctx.strokeRect(pt[0]-8,pt[1]-6,16,12);}else GF.Draw.text(ctx,'⌂',pt[0],pt[1],{size:19,color:o.color,weight:'900'});
  GF.Draw.text(ctx,parcel?'PARCEL DEPOT':o.name,pt[0],pt[1]-44,{size:13,color:C.ink,weight:'900'});ctx.restore();
 },
 draw(ctx){
  const bg=ctx.createLinearGradient(0,0,960,540);bg.addColorStop(0,'#5bc8c8');bg.addColorStop(1,C.water);ctx.fillStyle=bg;ctx.fillRect(0,0,960,540);
  ctx.strokeStyle='rgba(245,241,223,.54)';ctx.lineWidth=2;for(let y=77;y<540;y+=31)for(let x=(y*3)%82;x<960;x+=88){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+20,y);ctx.stroke();}
  ctx.fillStyle=C.sand;ctx.fillRect(30,70,900,440);ctx.fillStyle=C.road;ctx.fillRect(48,225,864,92);ctx.fillRect(72,120,95,305);ctx.fillRect(335,105,72,350);ctx.fillRect(575,105,72,350);ctx.fillRect(790,105,74,350);
  ctx.strokeStyle=C.curb;ctx.lineWidth=3;ctx.setLineDash([12,13]);ctx.beginPath();ctx.moveTo(55,271);ctx.lineTo(905,271);ctx.stroke();ctx.setLineDash([]);
  for(const b of this.blocks){
   if(b.type==='building'){GF.Draw.roundRect(ctx,b.x+5,b.y+7,b.w,b.h,13,'rgba(20,68,90,.18)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.x===418?C.coral:C.sand);ctx.fillStyle='rgba(255,249,232,.7)';for(let xx=b.x+18;xx<b.x+b.w-10;xx+=29)ctx.fillRect(xx,b.y+25,12,18);}
   else if(b.type==='planter'||b.type==='hedge'){GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,10,'#d98b57');GF.Draw.roundRect(ctx,b.x+5,b.y+5,b.w-10,b.h-10,8,C.leaf);}
   else{ctx.strokeStyle='#8b6044';ctx.lineWidth=5;for(let yy=b.y;yy<b.y+b.h;yy+=17){ctx.beginPath();ctx.moveTo(b.x,yy);ctx.lineTo(b.x+b.w,yy);ctx.stroke();}}
  }
  ctx.fillStyle='#f7f0df';ctx.beginPath();ctx.moveTo(875,445);ctx.lineTo(910,445);ctx.lineTo(900,428);ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(895,445);ctx.lineTo(895,410);ctx.stroke();
  const active=this.orders[Math.min(this.order,2)],goal=this.objective();ctx.save();ctx.strokeStyle=this.carry?active.color:C.leaf;ctx.globalAlpha=.52;ctx.lineWidth=3;ctx.setLineDash([8,9]);ctx.lineDashOffset=-game.time*35;ctx.beginPath();ctx.moveTo(this.x,this.y);ctx.lineTo(goal[0],goal[1]);ctx.stroke();ctx.restore();
  for(let i=this.order;i<3;i++){const o=this.orders[i];if(i===this.order&&this.carry)this.marker(ctx,o.home,o,false,false);else this.marker(ctx,o.depot,o,true,i!==this.order);}
  for(const r of this.rings){ctx.globalAlpha=r.life;ctx.strokeStyle=r.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
  ctx.save();ctx.translate(this.x,this.y);ctx.rotate(Math.atan2(this.vy,this.vx)||0);ctx.fillStyle='rgba(20,50,60,.2)';ctx.beginPath();ctx.ellipse(1,11,24,8,0,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-18,-10,36,20,9,C.coral);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.strokeRect(-15,-7,30,14);ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(-12,12,6,0,Math.PI*2);ctx.arc(12,12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=C.cream;ctx.fillRect(4,-6,13,8);if(this.carry){ctx.fillStyle=active.color;ctx.fillRect(-4,-24,16,13);ctx.strokeStyle=C.ink;ctx.lineWidth=2;ctx.strokeRect(-4,-24,16,13);}ctx.restore();
  GF.Draw.roundRect(ctx,16,14,170,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'TIME  '+Math.ceil(this.timer)+'s',29,38,{size:23,color:this.timer<=10?C.coral:C.cream,align:'left'});
  GF.Draw.roundRect(ctx,202,14,326,48,12,'rgba(255,249,232,.96)');GF.Draw.text(ctx,this.carry?'DELIVER: '+active.name:'PICK UP: Parcel Depot',218,38,{size:17,color:C.ink,align:'left'});
  GF.Draw.roundRect(ctx,610,14,150,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'DELIVERIES',685,29,{size:11,color:'#bde6df'});GF.Draw.text(ctx,this.order+' / 3',685,48,{size:20,color:C.cream});
  GF.Draw.roundRect(ctx,778,14,166,48,12,'rgba(23,68,90,.94)');GF.Draw.text(ctx,'SCORE '+game.score,792,39,{size:20,color:C.sand,align:'left'});GF.Draw.text(ctx,'WASD / ARROWS • follow the route ribbon',480,520,{size:14,color:C.ink,weight:'900'});GF.Draw.vignette(ctx,960,540,.12);
 }
};
game.add('play',play);game.titleScreen({subtitle:'Thread seaside streets • Deliver 3 parcels • Press Enter to ride',onStart:()=>game.go('play')});
